/// Largest accepted path, in bytes excluding the terminating NUL used by C.
pub const MAX_ATOMIC_FILE_PATH_BYTES: usize = 1023;

/// Failure classes returned by atomic replacement of an existing file.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AtomicFileReplaceError {
    Ok,
    Invalid,
    PathLimit,
    NotFound,
    NotRegular,
    Io,
    Durability,
    Unknown,
}

impl fmt::Display for AtomicFileReplaceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Ok => "ok",
            Self::Invalid => "invalid",
            Self::PathLimit => "path_limit",
            Self::NotFound => "not_found",
            Self::NotRegular => "not_regular",
            Self::Io => "io",
            Self::Durability => "durability",
            Self::Unknown => "unknown",
        })
    }
}

impl std::error::Error for AtomicFileReplaceError {}

/// Failure classes returned by atomic no-replace publication.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AtomicFileCreateNewError {
    Ok,
    Invalid,
    PathLimit,
    Exists,
    Io,
    Durability,
}

impl fmt::Display for AtomicFileCreateNewError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Ok => "ok",
            Self::Invalid => "invalid",
            Self::PathLimit => "path_limit",
            Self::Exists => "exists",
            Self::Io => "io",
            Self::Durability => "durability",
        })
    }
}

impl std::error::Error for AtomicFileCreateNewError {}

/// Safe borrowed hooks for deterministic failure and race tests.
pub trait AtomicFileReplaceHooks {
    fn write(&mut self, file: &mut File, bytes: &[u8]) -> io::Result<usize> {
        use std::io::Write;
        file.write(bytes)
    }

    fn sync_file(&mut self, file: &File) -> io::Result<()> {
        file.sync_all()
    }

    /// Consumes the file even when returning an error; implementations must
    /// consume its descriptor exactly once.
    fn close_file(&mut self, file: File) -> io::Result<()> {
        crate::sys::close_checked(file.into())
    }

    fn rename(&mut self, from: &Path, to: &Path) -> io::Result<()> {
        std::fs::rename(from, to)
    }

    fn sync_directory(&mut self, directory: &Path) -> io::Result<()> {
        File::open(directory)?.sync_all()
    }
}

/// Safe borrowed hooks for deterministic failure and publication-race tests.
pub trait AtomicFileCreateNewHooks {
    fn write(&mut self, file: &mut File, bytes: &[u8]) -> io::Result<usize> {
        use std::io::Write;
        file.write(bytes)
    }

    fn sync_file(&mut self, file: &File) -> io::Result<()> {
        file.sync_all()
    }

    /// Consumes the file even when returning an error; implementations must
    /// consume its descriptor exactly once.
    fn close_file(&mut self, file: File) -> io::Result<()> {
        crate::sys::close_checked(file.into())
    }

    fn publish(&mut self, temporary: &Path, target: &Path) -> io::Result<()> {
        std::fs::hard_link(temporary, target)
    }

    fn remove_temporary(&mut self, temporary: &Path) -> io::Result<()> {
        std::fs::remove_file(temporary)
    }

    fn sync_directory(&mut self, directory: &Path) -> io::Result<()> {
        File::open(directory)?.sync_all()
    }
}

