#[derive(Default)]
struct Script {
    interrupt_write: bool,
    max_write: usize,
    fail_write: bool,
    zero_write: bool,
    fail_sync: bool,
    fail_close_at: usize,
    fail_rename: bool,
    fail_publish: bool,
    race_publish: bool,
    fail_directory_sync: bool,
    fail_remove_once: bool,
    writes: usize,
    closes: usize,
}

impl Script {
    fn write_chunk(&mut self, file: &mut File, bytes: &[u8]) -> io::Result<usize> {
        self.writes += 1;
        if self.interrupt_write {
            self.interrupt_write = false;
            return Err(io::Error::from(io::ErrorKind::Interrupted));
        }
        if self.fail_write {
            return Err(io::Error::from(io::ErrorKind::Other));
        }
        if self.zero_write {
            return Ok(0);
        }
        let end = bytes.len().min(self.max_write.max(1));
        file.write(&bytes[..end])
    }

    fn sync(&mut self, file: &File) -> io::Result<()> {
        if self.fail_sync {
            Err(io::Error::from(io::ErrorKind::Other))
        } else {
            file.sync_all()
        }
    }

    fn close(&mut self, file: File) -> io::Result<()> {
        self.closes += 1;
        crate::sys::close_checked(file.into())?;
        if self.fail_close_at == self.closes {
            Err(io::Error::from(io::ErrorKind::Other))
        } else {
            Ok(())
        }
    }

    fn sync_dir(&mut self, directory: &Path) -> io::Result<()> {
        if self.fail_directory_sync {
            Err(io::Error::from(io::ErrorKind::Other))
        } else {
            File::open(directory)?.sync_all()
        }
    }
}

impl AtomicFileReplaceHooks for Script {
    fn write(&mut self, file: &mut File, bytes: &[u8]) -> io::Result<usize> {
        self.write_chunk(file, bytes)
    }

    fn sync_file(&mut self, file: &File) -> io::Result<()> {
        self.sync(file)
    }

    fn close_file(&mut self, file: File) -> io::Result<()> {
        self.close(file)
    }

    fn rename(&mut self, from: &Path, to: &Path) -> io::Result<()> {
        if self.fail_rename {
            Err(io::Error::from(io::ErrorKind::Other))
        } else {
            fs::rename(from, to)
        }
    }

    fn sync_directory(&mut self, directory: &Path) -> io::Result<()> {
        self.sync_dir(directory)
    }
}

impl AtomicFileCreateNewHooks for Script {
    fn write(&mut self, file: &mut File, bytes: &[u8]) -> io::Result<usize> {
        self.write_chunk(file, bytes)
    }

    fn sync_file(&mut self, file: &File) -> io::Result<()> {
        self.sync(file)
    }

    fn close_file(&mut self, file: File) -> io::Result<()> {
        self.close(file)
    }

    fn publish(&mut self, temporary: &Path, target: &Path) -> io::Result<()> {
        if self.race_publish {
            let mut competitor = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(target)?;
            competitor.write_all(b"racing writer")?;
            crate::sys::close_checked(competitor.into())?;
        }
        if self.fail_publish {
            Err(io::Error::from(io::ErrorKind::Other))
        } else {
            fs::hard_link(temporary, target)
        }
    }

    fn remove_temporary(&mut self, temporary: &Path) -> io::Result<()> {
        if self.fail_remove_once {
            self.fail_remove_once = false;
            Err(io::Error::from(io::ErrorKind::Other))
        } else {
            fs::remove_file(temporary)
        }
    }

    fn sync_directory(&mut self, directory: &Path) -> io::Result<()> {
        self.sync_dir(directory)
    }
}

